"""Schema64: source-isolated supplier watches, history and local notifications."""

SUPPLIER_WATCH_DDL = (
    "CREATE TABLE supplier_watches (id TEXT PRIMARY KEY NOT NULL, supplier_id TEXT NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT, source_key TEXT NOT NULL CHECK (source_key IN ('threatcluster','ransomlook','hibp')), active INTEGER NOT NULL CHECK (active IN (0,1)), revision INTEGER NOT NULL CHECK (revision>0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (supplier_id,source_key))",
    "CREATE TABLE supplier_watch_events (sequence INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, id TEXT NOT NULL UNIQUE, watch_id TEXT NOT NULL REFERENCES supplier_watches(id) ON DELETE RESTRICT, supplier_id TEXT NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT, source_key TEXT NOT NULL CHECK (source_key IN ('threatcluster','ransomlook','hibp')), action TEXT NOT NULL CHECK (action IN ('enabled','disabled')), revision INTEGER NOT NULL CHECK (revision>0), reason TEXT NOT NULL, recorded_at TEXT NOT NULL, UNIQUE(watch_id,revision))",
    "CREATE TABLE supplier_watch_runs (sequence INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, id TEXT NOT NULL UNIQUE, watch_id TEXT NOT NULL REFERENCES supplier_watches(id) ON DELETE RESTRICT, supplier_id TEXT NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT, source_key TEXT NOT NULL CHECK (source_key IN ('threatcluster','ransomlook','hibp')), threatcluster_run_id TEXT REFERENCES ransomware_claim_runs(id) ON DELETE RESTRICT, ransomlook_run_id TEXT REFERENCES ransomlook_claim_runs(id) ON DELETE RESTRICT, public_notice_run_id TEXT REFERENCES public_notice_runs(id) ON DELETE RESTRICT, watch_event_id TEXT NOT NULL REFERENCES supplier_watch_events(id) ON DELETE RESTRICT, previous_run_id TEXT REFERENCES supplier_watch_runs(id) ON DELETE RESTRICT, supplier_event_sequence INTEGER NOT NULL CHECK (supplier_event_sequence>0), recorded_at TEXT NOT NULL, scope_json TEXT NOT NULL, scope_sha256 TEXT NOT NULL, result_sha256 TEXT NOT NULL, matched_count INTEGER NOT NULL CHECK (matched_count BETWEEN 0 AND 10000), baseline_count INTEGER NOT NULL CHECK (baseline_count BETWEEN 0 AND 10000), added_count INTEGER NOT NULL CHECK (added_count BETWEEN 0 AND 10000), updated_count INTEGER NOT NULL CHECK (updated_count BETWEEN 0 AND 10000), removed_count INTEGER NOT NULL CHECK (removed_count BETWEEN 0 AND 10000), unchanged_count INTEGER NOT NULL CHECK (unchanged_count BETWEEN 0 AND 10000), UNIQUE(watch_id,threatcluster_run_id), UNIQUE(watch_id,ransomlook_run_id), UNIQUE(watch_id,public_notice_run_id), CHECK (matched_count=baseline_count+added_count+updated_count+unchanged_count), CHECK ((source_key='threatcluster' AND threatcluster_run_id IS NOT NULL AND ransomlook_run_id IS NULL AND public_notice_run_id IS NULL) OR (source_key='ransomlook' AND threatcluster_run_id IS NULL AND ransomlook_run_id IS NOT NULL AND public_notice_run_id IS NULL) OR (source_key='hibp' AND threatcluster_run_id IS NULL AND ransomlook_run_id IS NULL AND public_notice_run_id IS NOT NULL)))",
    "CREATE TABLE supplier_watch_notifications (sequence INTEGER PRIMARY KEY NOT NULL CHECK (sequence>0), id TEXT NOT NULL UNIQUE, run_id TEXT NOT NULL UNIQUE REFERENCES supplier_watch_runs(id) ON DELETE RESTRICT, watch_id TEXT NOT NULL REFERENCES supplier_watches(id) ON DELETE RESTRICT, supplier_id TEXT NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT, source_key TEXT NOT NULL CHECK (source_key IN ('threatcluster','ransomlook','hibp')), event_type TEXT NOT NULL CHECK (event_type='supplier_watch_changed'), origin TEXT NOT NULL CHECK (origin='new'), created_at TEXT NOT NULL, read_at TEXT)",
    "CREATE INDEX supplier_watches_active_source ON supplier_watches(active,source_key)",
    "CREATE INDEX supplier_watch_events_watch_sequence ON supplier_watch_events(watch_id,sequence)",
    "CREATE INDEX supplier_watch_runs_watch_sequence ON supplier_watch_runs(watch_id,sequence)",
    "CREATE INDEX supplier_watch_notifications_read_sequence ON supplier_watch_notifications(read_at,sequence)",
)
